let products = defaultProducts.map(p => ({...p}));

function normalizeProductRow(row, fallback){
  const get = (...keys) => {
    for (const key of keys){
      const v = row[key] ?? row[key.toLowerCase()] ?? row[key.toUpperCase()];
      if(v !== undefined && String(v).trim() !== '') return String(v).trim();
    }
    return '';
  };
  const id = get('id') || (fallback && fallback.id) || (get('name') || '').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
  const priceRaw = get('price').replace(/[^0-9.]/g,'');
  return {
    ...(fallback || {}),
    id,
    name: get('name') || (fallback && fallback.name) || id,
    category: get('category') || (fallback && fallback.category) || 'unisex',
    badge: get('badge') || (fallback && fallback.badge) || '',
    price: priceRaw ? Number(priceRaw) : ((fallback && fallback.price) || 0),
    gender: get('gender') || (fallback && fallback.gender) || 'Unisex Fragrance',
    family: get('family') || (fallback && fallback.family) || '',
    desc: get('desc','description') || (fallback && fallback.desc) || '',
    notes: get('notes') || (fallback && fallback.notes) || '',
    longevity: get('longevity') || (fallback && fallback.longevity) || '',
    projection: get('projection') || (fallback && fallback.projection) || '',
    image: get('image','image_url') || (fallback && fallback.image) || ''
  };
}

function parseCsv(text){
  const rows=[]; let row=[]; let cur=''; let q=false;
  for(let i=0;i<text.length;i++){
    const c=text[i], n=text[i+1];
    if(c==='"' && q && n==='"'){cur+='"'; i++; continue;}
    if(c==='"'){q=!q; continue;}
    if(c===',' && !q){row.push(cur); cur=''; continue;}
    if((c==='\n' || c==='\r') && !q){
      if(c==='\r' && n==='\n') i++;
      row.push(cur); cur='';
      if(row.some(x=>String(x).trim()!=='')) rows.push(row);
      row=[]; continue;
    }
    cur+=c;
  }
  row.push(cur); if(row.some(x=>String(x).trim()!=='')) rows.push(row);
  if(!rows.length) return [];
  const headers=rows.shift().map(h=>String(h).trim());
  return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h, r[i] || ''])));
}

async function loadProductsFromGoogleSheet(){
  const url = (window.ATYAB_PRODUCTS_CSV_URL || '').trim();
  if(!url) return false;
  try{
    const res = await fetch(url, {cache:'no-store'});
    if(!res.ok) throw new Error('Sheet not reachable');
    const rows = parseCsv(await res.text());
    if(!rows.length) throw new Error('Sheet is empty');
    const byId = Object.fromEntries(defaultProducts.map(p=>[p.id,p]));
    products = rows.map(row => normalizeProductRow(row, byId[(row.id || '').trim()])).filter(p=>p.id && p.name);
    if(!products.length) products = defaultProducts.map(p => ({...p}));
    return true;
  }catch(err){
    console.warn('ATYAB Google Sheet loading failed. Default products are being used.', err);
    products = defaultProducts.map(p => ({...p}));
    return false;
  }
}

async function initProducts(){
  await loadProductsFromGoogleSheet();
  renderProducts();
}

