function addToCart(id, qty=1, size='50ml', bottle='Black Bottle'){
  size = '50ml'; // ATYAB products are currently available in 50ml only
  bottle = bottleLabel(bottle);
  const found=cart.find(i=>i.id===id && i.size===size && bottleLabel(i.bottle)===bottle);
  if(found) found.qty+=qty; else cart.push({id,qty,size,bottle});
  saveCart(); toast(productById(id).name + ' added to cart'); openCart();
}
function removeFromCart(id,size,bottle='Black Bottle'){ bottle=bottleLabel(bottle); cart=cart.filter(i=>!(i.id===id && i.size===size && bottleLabel(i.bottle)===bottle)); saveCart(); renderCartPage(); renderCheckout(); }
function changeQty(id,size,bottle,delta){ bottle=bottleLabel(bottle); const item=cart.find(i=>i.id===id && i.size===size && bottleLabel(i.bottle)===bottle); if(!item) return; item.qty+=delta; if(item.qty<=0) removeFromCart(id,size,bottle); else {saveCart(); renderCartPage(); renderCheckout();} }
function subtotal(){ return cart.reduce((s,i)=>s+(productById(i.id)?.price||0)*i.qty,0); }
function delivery(){ return subtotal()>=3200 || subtotal()===0 ? 0 : 250; }
function total(){ return subtotal()+delivery(); }
