  const foot=document.getElementById('cartFooter'); if(foot) foot.innerHTML = cart.length ? `${summaryHtml()}<div class="cart-footer-btns"><button class="btn-gold" onclick="showPage('checkout')">Checkout</button><button class="btn-outline" onclick="showPage('cart')">View Cart</button></div>` : '';
