function renderCheckout(){
  const items=document.getElementById('checkoutOrderItems'); if(items) items.innerHTML=cart.length ? cart.map(i=>{const p=productById(i.id);return `<div class="order-product-row"><span>${p.name} × ${i.qty}<small>${i.size} | ${bottleLabel(i.bottle)}</small></span><span>${formatPrice(p.price*i.qty)}</span></div>`}).join('') : '<p style="color:var(--text-muted);">No items in cart.</p>';
  const s=document.getElementById('co_subtotal'); if(s) s.textContent=formatPrice(subtotal());
  const d=document.getElementById('co_delivery'); if(d) d.textContent=delivery()?formatPrice(delivery()):'Free';
  const t=document.getElementById('co_total'); if(t) t.textContent=formatPrice(total());
}
function selectPayment(el){
  document.querySelectorAll('.radio-opt').forEach(x=>x.classList.remove('selected'));
  el.closest('.radio-opt')?.classList.add('selected');
  const isCOD = el.value === 'Cash on Delivery';
  const details = document.getElementById('paymentDetails');
  const trans = document.getElementById('co_transaction');
  const shot = document.getElementById('co_screenshot');
  const shotGroup = document.getElementById('screenshot_group');
  if(details) details.style.opacity = isCOD ? '0.55' : '1';
  if(trans){
    trans.required = !isCOD;
    trans.value = isCOD ? '' : trans.value;
    trans.placeholder = isCOD ? 'Not required for Cash on Delivery' : 'Enter payment transaction ID';
  }
  if(shot){
    shot.required = !isCOD;
    if(isCOD) shot.value = '';
  }
  if(shotGroup){
    shotGroup.style.display = isCOD ? 'none' : 'block';
  }
}

function orderText(){
  const name=document.getElementById('co_name')?.value.trim()||''; const phone=document.getElementById('co_phone')?.value.trim()||''; const email=document.getElementById('co_email')?.value.trim()||''; const city=document.getElementById('co_city')?.value.trim()||''; const address=document.getElementById('co_address')?.value.trim()||''; const notes=document.getElementById('co_notes')?.value.trim()||'';
  const payment=document.querySelector('input[name="payment"]:checked')?.value || 'Cash on Delivery';
  const transaction=document.getElementById('co_transaction')?.value.trim()||'';
  const lines=cart.map(i=>{const p=productById(i.id); return `- ${p.name} (${i.size}, ${bottleLabel(i.bottle)}) x ${i.qty} = ${formatPrice(p.price*i.qty)}`;}).join('\n');
  return `New ATYAB FRAGRANCE Order%0A%0ACustomer Name: ${name}%0APhone: ${phone}%0AEmail: ${email || 'N/A'}%0ACity: ${city}%0AAddress: ${address}%0APayment: ${payment}%0ATransaction ID: ${transaction || 'Not provided'}%0A%0AProducts:%0A${lines.replace(/\n/g,'%0A')}%0A%0ASubtotal: ${formatPrice(subtotal())}%0ADelivery: ${delivery()?formatPrice(delivery()):'Free'}%0ATotal: ${formatPrice(total())}%0A%0ANotes: ${notes || 'N/A'}`;
}

function readPaymentScreenshot(){
  return new Promise((resolve, reject) => {
    const input = document.getElementById('co_screenshot');
    const file = input?.files?.[0];
    if(!file){ resolve(null); return; }
    if(!file.type.startsWith('image/')){
      reject(new Error('Please upload an image file only.'));
      return;
    }
    if(file.size > 2 * 1024 * 1024){
      reject(new Error('Payment screenshot image is too large. Please upload an image under 2MB, or compress it and try again.'));
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      const result = String(reader.result || '');
      const base64 = result.includes(',') ? result.split(',')[1] : result;
      resolve({
        screenshotName: file.name,
        screenshotMime: file.type,
        screenshotData: base64
      });
    };
    reader.onerror = () => reject(new Error('Could not read payment screenshot. Please try again.'));
    reader.readAsDataURL(file);
  });
}

async function placeOrder(){
  if(cart.length===0){ alert('Your cart is empty.'); showPage('shop'); return; }
  const req=['co_name','co_phone','co_email','co_city','co_address'];
  for(const id of req){ const el=document.getElementById(id); if(!el || !el.value.trim()){ alert('Please fill all required delivery fields.'); el?.focus(); return; } }

  const selectedPayment=document.querySelector('input[name="payment"]:checked')?.value || 'Cash on Delivery';
  const transactionValue=document.getElementById('co_transaction')?.value.trim()||'';
  const screenshotInput=document.getElementById('co_screenshot');

  if(selectedPayment !== 'Cash on Delivery'){
    if(!transactionValue){
      alert('Please enter Transaction ID / Reference Number for advance payment.');
      document.getElementById('co_transaction')?.focus();
      return;
    }
    if(!screenshotInput?.files?.[0]){
      alert('Please upload your payment screenshot for advance payment verification.');
      screenshotInput?.focus();
      return;
    }
  }

  const name=document.getElementById('co_name')?.value.trim()||'';
  const phone=document.getElementById('co_phone')?.value.trim()||'';
  const email=document.getElementById('co_email')?.value.trim()||'';
  const city=document.getElementById('co_city')?.value.trim()||'';
  const address=document.getElementById('co_address')?.value.trim()||'';
  const notes=document.getElementById('co_notes')?.value.trim()||'';
  const payment=document.querySelector('input[name="payment"]:checked')?.value || 'Cash on Delivery';
  const transaction=transactionValue;
  const productsText=cart.map(i=>{const p=productById(i.id); return `${p.name} (${i.size}, ${bottleLabel(i.bottle)}) x ${i.qty}`;}).join(', ');
  const quantity=cart.reduce((sum,i)=>sum+i.qty,0);
  const amount=formatPrice(total());

  let screenshotPayload = null;
  try{
    screenshotPayload = await readPaymentScreenshot();
  }catch(err){
    alert(err.message || 'Payment screenshot could not be read.');
    return;
  }

  const payload={
    name, phone, email, city, address,
    products: productsText,
    quantity: String(quantity),
    amount,
    paymentMethod: payment,
    transactionId: transaction,
    notes,
    screenshotName: screenshotPayload?.screenshotName || '',
    screenshotMime: screenshotPayload?.screenshotMime || '',
    screenshotData: screenshotPayload?.screenshotData || ''
  };

  const btn = event?.target;
  if(btn){ btn.disabled=true; btn.innerHTML='<i class="fas fa-spinner fa-spin"></i> Placing Order...'; }

  try{
    await Promise.race([
      fetch(GOOGLE_SCRIPT_URL, {
        method:'POST',
        mode:'no-cors',
        headers:{ 'Content-Type':'text/plain;charset=utf-8' },
        body: JSON.stringify(payload)
      }),
      new Promise(resolve => setTimeout(resolve, 2500))
    ]);
  }catch(err){
    console.error('Google Sheet submit error:', err);
    alert('Order could not be saved to Google Sheet. Please check internet/App Script deployment, then try again.');
    if(btn){ btn.disabled=false; btn.innerHTML='<i class="fas fa-lock"></i> Place Order'; }
    return;
  }

  const text=orderText();
  localStorage.setItem('atyab_last_order', text);
  window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${text}`, '_blank');
  cart=[]; saveCart(); showPage('success');
  if(btn){ btn.disabled=false; btn.innerHTML='<i class="fas fa-lock"></i> Place Order'; }
}
