function openProduct(id){
  const p=productById(id); if(!p) return;
  document.getElementById('pdPageTitle').innerHTML = `${p.name.split(' ')[0]} <span>${p.name.split(' ').slice(1).join(' ')||'Fragrance'}</span>`;
  document.getElementById('pdBreadcrumb').textContent = p.name;
  const el=document.getElementById('productDetailContent');
  el.innerHTML = `<div><div class="product-img-wrap" style="height:520px;"><img loading="lazy" decoding="async" id="pdMainBottleImg" class="product-img pd-main-bottle-img" src="${BOTTLE_BLACK_IMAGE}" alt="Black Bottle"></div></div><div><span class="section-label">${p.gender}</span><h2 class="section-title" style="text-align:left;">${p.name}</h2><div style="color:var(--gold);margin:10px 0;">★★★★★</div><h3 style="color:var(--gold);font-size:28px;margin:12px 0;">${formatPrice(p.price)}</h3><p style="color:var(--text-light);line-height:1.8;margin-bottom:18px;">${p.desc}</p><div class="form-group"><label>Size</label><select class="form-control" id="pdSize"><option selected>50ml</option></select><small style="display:block;color:var(--text-muted);margin-top:8px;">Currently available in 50ml only.</small></div><div class="form-group"><label>Bottle Type</label><input type="hidden" id="pdBottle" value="Black Bottle"><div class="bottle-options"><div class="bottle-option active" data-bottle="Black Bottle" onclick="selectBottleType(this)"><img loading="lazy" decoding="async" class="bottle-option-img" src="${BOTTLE_BLACK_IMAGE}" alt="Black Bottle"><div class="bottle-option-text"><strong>Black Bottle</strong><small>Elegant glossy luxury finish.</small></div></div><div class="bottle-option" data-bottle="White Frost Bottle" onclick="selectBottleType(this)"><img loading="lazy" decoding="async" class="bottle-option-img" src="${BOTTLE_WHITE_IMAGE}" alt="White Frost Bottle"><div class="bottle-option-text"><strong>White Frost Bottle</strong><small>Premium frosted glass finish.</small></div></div></div></div><div class="form-group"><label>Quantity</label><input id="pdQty" class="form-control" type="number" value="1" min="1" style="max-width:120px;"></div><div style="display:flex;gap:12px;flex-wrap:wrap;margin:20px 0;"><button class="btn-gold" onclick="addToCart('${p.id}', Number(document.getElementById('pdQty').value||1), document.getElementById('pdSize').value, getSelectedBottle())"><i class="fas fa-shopping-bag"></i> Add to Cart</button><button class="btn-outline" onclick="addToCart('${p.id}', Number(document.getElementById('pdQty').value||1), document.getElementById('pdSize').value, getSelectedBottle()); showPage('checkout')">Buy Now</button><button class="btn-outline" onclick="productWhatsAppOrder('${p.id}')"><i class="fab fa-whatsapp"></i> WhatsApp Order</button></div><div class="checkout-box"><h3>Fragrance Details</h3><p><strong>Notes:</strong> ${p.notes}</p><p><strong>Longevity:</strong> ${p.longevity}</p><p><strong>Projection:</strong> ${p.projection}</p><p><strong>Family:</strong> ${p.family}</p></div></div>`;
  renderRelated(id); showPage('product');
}
function renderRelated(current){ const el=document.getElementById('relatedGrid'); if(el) el.innerHTML=products.filter(p=>p.id!==current).slice(0,3).map(productCard).join(''); }
function quickView(id){
  const p=productById(id); if(!p) return;
  document.getElementById('modalTitle').textContent=p.name;
  document.getElementById('modalBody').innerHTML=`<div class="modal-product-grid"><div><img loading="lazy" decoding="async" src="${p.image || PRODUCT_IMAGE}" alt="${p.name}" style="max-width:100%;height:360px;object-fit:contain;"></div><div><span class="section-label">${p.gender}</span><h2 style="font-family:'Playfair Display',serif;color:var(--white);margin:10px 0;">${p.name}</h2><div style="color:var(--gold);">★★★★★</div><h3 style="color:var(--gold);font-size:24px;margin:14px 0;">${formatPrice(p.price)}</h3><p style="color:var(--text-light);line-height:1.7;">${p.desc}</p><p style="color:var(--text-muted);font-size:13px;"><strong>Notes:</strong> ${p.notes}</p><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:20px;"><button class="btn-gold" onclick="addToCart('${p.id}');closeModalBtn()">Add to Cart</button><button class="btn-outline" onclick="closeModalBtn();openProduct('${p.id}')">View Details</button></div></div></div>`;
  document.getElementById('modalOverlay')?.classList.add('open');
}
function closeModal(e){ if(e.target.id==='modalOverlay') closeModalBtn(); }
function closeModalBtn(){ document.getElementById('modalOverlay')?.classList.remove('open'); }
function renderReviews(){
  const defaultReviews=[['Ahsan R.','Dark Elixir','Long lasting and very premium fragrance. Packaging bhi bohat achi thi.','5'],['Hira K.','Soft Desire','Soft and elegant smell. Daily use ke liye perfect.','5'],['Usman A.','Blend X','Strong projection and luxury Arabic vibe.','5'],['Maham S.','Mystic Sage','Fresh and unique fragrance. I loved it.','5'],['Danish N.','Dark Elixir','Office aur evening dono ke liye best.','5'],['Sana F.','Soft Desire','Delivery fast thi aur fragrance long lasting hai.','5']];
  const saved=JSON.parse(localStorage.getItem('atyab_reviews')||'[]');
  const reviews=[...saved, ...defaultReviews];
  const el=document.getElementById('reviewsGrid'); if(el) el.innerHTML=reviews.map(r=>{const stars='★★★★★'.slice(0,Number(r[3]||5)) + '☆☆☆☆☆'.slice(0,5-Number(r[3]||5)); return `<div class="review-card"><div style="color:var(--gold);">${stars}</div><p style="color:var(--text-light);line-height:1.8;margin:14px 0;">“${r[2]}”</p><strong style="color:var(--white);">${r[0]}</strong><div class="review-product">${r[1]}</div></div>`}).join('');
}
function submitReview(){
  const name=document.getElementById('reviewName')?.value.trim()||'';
  const product=document.getElementById('reviewProduct')?.value||'';
  const rating=document.getElementById('reviewRating')?.value||'5';
  const city=document.getElementById('reviewCity')?.value.trim()||'';
  const text=document.getElementById('reviewText')?.value.trim()||'';
  if(!name || !text){ alert('Please enter your name and review.'); return; }
  const saved=JSON.parse(localStorage.getItem('atyab_reviews')||'[]');
  saved.unshift([name, product, text, rating, city]);
  localStorage.setItem('atyab_reviews', JSON.stringify(saved));
  renderReviews();
  const msg=`New ATYAB Review%0AName: ${encodeURIComponent(name)}%0ACity: ${encodeURIComponent(city || 'N/A')}%0AProduct: ${encodeURIComponent(product)}%0ARating: ${rating}/5%0AReview: ${encodeURIComponent(text)}`;
  window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${msg}`, '_blank');
  alert('Thank you! Your review has been added and sent for verification.');
  ['reviewName','reviewCity','reviewText'].forEach(id=>{const el=document.getElementById(id); if(el) el.value='';});
}
function toast(msg){
  let t=document.getElementById('toast'); if(!t){ t=document.createElement('div'); t.id='toast'; t.style.cssText='position:fixed;left:50%;bottom:25px;transform:translateX(-50%);background:#111;color:#fff;border:1px solid rgba(201,168,76,.45);padding:12px 18px;z-index:9999;opacity:0;transition:.25s;box-shadow:0 10px 30px rgba(0,0,0,.35);'; document.body.appendChild(t); }
  t.textContent=msg; t.style.opacity='1'; setTimeout(()=>t.style.opacity='0',2200);
}
(function init(){
  const st=document.createElement('style'); st.textContent=`.float-wa{position:fixed;right:22px;bottom:22px;width:56px;height:56px;border-radius:50%;background:#25D366;color:white;display:flex;align-items:center;justify-content:center;font-size:28px;z-index:900;text-decoration:none;box-shadow:0 10px 28px rgba(0,0,0,.35)} .qty-control{display:flex;align-items:center;gap:8px;margin-top:10px}.qty-control button{background:rgba(201,168,76,.1);border:1px solid var(--border-gold);color:var(--gold);padding:5px 9px;cursor:pointer}.page{display:none}.page.active{display:block}.modal-overlay.open{opacity:1;pointer-events:all}.modal-overlay{opacity:0;pointer-events:none}`; document.head.appendChild(st);
  initProducts(); updateCartUI(); renderCheckout();
})();